class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "..."

class Cat(Animal):
    def speak(self):
        return "meow"

class Dog(Animal):
    def speak(self):
        return "woof"

for pet in (Cat("Mili"), Dog("Bruno")):
    print(pet.name, pet.speak())

class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def describe(self):
        return f"{self.owner}: {self.balance}"

class Savings(Account):
    def __init__(self, owner, balance=0, rate=0.05):
        super().__init__(owner, balance)
        self.rate = rate

    def describe(self):
        return super().describe() + f" (rate {self.rate})"

account = Savings("Asha", 1000)
print(account.describe())
print(isinstance(account, Account), isinstance(account, Savings))

