class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __eq__(self, other):
        return isinstance(other, Point) and (self.x, self.y) == (other.x, other.y)

    def __repr__(self):
        return f"Point({self.x}, {self.y})"

print(Point(1, 2) == Point(1, 2))
print(Point(1, 2) == Point(3, 4))
print([Point(0, 1)])

